const $=id=>document.getElementById(id);let config,worker,usernameLocked=false;
function notice(text){$('notice').textContent=text}
async function api(path,method='GET',body){const response=await fetch('/api/v1'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw Error('Background service unavailable. Start npm run service; static hosting cannot run scheduled updates.')}if(response.status===401){$('login-panel').hidden=false;$('connected').hidden=true;throw Error('Sign in with your owner token.')}if(!response.ok)throw Error(data.error||'Request failed.');return data}
const date=at=>at?new Date(at).toLocaleString([], {timeZone:config.timezone}):'Off';
function fill(){
 $('username-setting').value=config.username;$('username-setting').disabled=usernameLocked;$('username-note').textContent=usernameLocked?'This account is set by the server configuration, so it cannot be changed here.':'The service uses this account while your browser is closed. Moves still happen in Sleeper.';$('excluded').value=config.disabled.join(', ');$('timezone').value=config.timezone;
 for(const period of ['daily','weekly']){$(period+'-enabled').checked=config[period].enabled;$(period+'-time').value=config[period].time}$('weekly-day').value=config.weekly.day;
 $('trade-alerts').checked=config.alerts.trades;for(const [id,key]of [['min-gain','minGain'],['improvement','improvement'],['cooldown','cooldownHours'],['daily-cap','dailyCap'],['quiet-start','quietStart'],['quiet-end','quietEnd']])$(id).value=config.alerts[key];
}
function activity(){
 $('ntfy-status').textContent=worker.ntfyConfigured?'ntfy is configured. Test delivery before enabling alerts.':'ntfy is not configured. Scheduled reports will still be archived here.';$('test').disabled=!worker.ntfyConfigured;
 $('schedule-status').textContent=`Next daily: ${date(worker.nextDaily)} · Next weekly: ${date(worker.nextWeekly)} (${config.timezone})`;
 $('worker-status').textContent=worker.lastError?`${worker.lastError.message} Last attempted ${date(worker.lastError.at)}.`:`Last background run: ${date(worker.lastRun)}. Checks run every minute; trade scans run every 15 minutes.`;
 $('delivery-status').replaceChildren();for(const item of worker.outbox.slice(-5).reverse()){const p=document.createElement('p');p.textContent=`${item.title}: ${item.status}${item.error?' · '+item.error:''}`;$('delivery-status').append(p)}
 $('reports').replaceChildren();if(!worker.reports.length)$('reports').textContent='No reports yet. Enable a schedule or preview a report above.';
 for(const report of worker.reports){const d=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent=`${report.period} · ${date(report.createdAt)} · ${report.delivery}`;pre.textContent=report.text;d.append(summary,pre);$('reports').append(d)}
}
async function load(){const result=await api('/settings');config=result.settings;worker=result.worker;usernameLocked=!!result.usernameLocked;fill();activity();$('login-panel').hidden=true;$('connected').hidden=false;$('logout').hidden=!result.authRequired;notice(result.authRequired?'Connected. Save changes to update your background service.':'Save changes to update your background service.');if(config.username){try{const {data}=await api('/client');$('league-list').textContent=data.leagues.map(l=>`${l.name}: ${l.league_id}`).join(' · ')}catch(e){notice(e.message)}}}
$('login').addEventListener('submit',async e=>{e.preventDefault();try{await api('/session','POST',{token:$('owner-token').value});$('owner-token').value='';await load()}catch(e){notice(e.message)}});
$('settings-form').addEventListener('submit',async e=>{e.preventDefault();$('save').disabled=true;try{
 const next={...config,username:usernameLocked?config.username:$('username-setting').value.trim(),disabled:$('excluded').value.split(',').map(x=>x.trim()).filter(Boolean),timezone:$('timezone').value.trim(),daily:{enabled:$('daily-enabled').checked,time:$('daily-time').value},weekly:{enabled:$('weekly-enabled').checked,time:$('weekly-time').value,day:Number($('weekly-day').value)},alerts:{trades:$('trade-alerts').checked,minGain:Number($('min-gain').value),improvement:Number($('improvement').value),cooldownHours:Number($('cooldown').value),dailyCap:Number($('daily-cap').value),quietStart:$('quiet-start').value,quietEnd:$('quiet-end').value}};
 await api('/settings','PUT',next);await load();notice('Settings saved. Your schedules work while the browser is closed.');
 }catch(e){notice(e.message)}finally{$('save').disabled=false}});
$('import').addEventListener('click',()=>{try{const p=JSON.parse(localStorage.getItem('sunday-preferences')||'{}');if(!p.username)throw Error('No connected Sleeper account is saved in this browser.');if(!usernameLocked)config.username=p.username;config.disabled=p.disabled||[];config.preferences=Object.fromEntries(['tradeMinGain','tradeMaxGap','tradeEndWeek','tradePenalty','tradeExcluded','waiverExcluded','waiverProtected','protectStarters','samePositionDrops','waiverUpgradesOnly','requireBenefit'].filter(k=>k in p).map(k=>[k,p[k]]));if(!config.preferences.waiverExcluded&&p.waiverIncluded)config.preferences.waiverExcluded={add:['QB','RB','WR','TE','K','DEF'].filter(x=>!p.waiverIncluded.includes(x)),drop:[]};fill();notice('Account and analysis preferences imported. Save settings to apply them.')}catch(e){notice(e.message)}});
for(const [id,period]of [['preview','daily'],['preview-weekly','weekly']])$(id).addEventListener('click',async()=>{$(id).disabled=true;notice('Loading report data…');try{const report=await api('/digests/preview','POST',{period});$('preview-content').hidden=false;$('preview-content').textContent=report.text;notice('Preview ready. No notification was sent.')}catch(e){notice(e.message)}finally{$(id).disabled=false}});
$('test').addEventListener('click',async()=>{$('test').disabled=true;try{await api('/notifications/test','POST',{});notice('ntfy accepted the test notification. Check your subscribed device.')}catch(e){notice(e.message)}finally{$('test').disabled=false}});
$('reload').addEventListener('click',async()=>{try{const result=await api('/settings');worker=result.worker;activity();notice('Activity refreshed.')}catch(e){notice(e.message)}});
$('logout').addEventListener('click',async()=>{try{await api('/session','DELETE');location.reload()}catch(e){notice(e.message)}});
load().catch(e=>notice(e.message));
